pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 fuzzSeed) public {
        // fuzzSeed drives block.difficulty and block.timestamp to influence randomness
        vm.roll(fuzzSeed % 1000 + 1);
        vm.warp(fuzzSeed % 100000 + 1);

        address player = address(0x1234);
        vm.deal(player, 10 ether);
        vm.prank(player);

        // Play with exact ticket amount
        c.play{value: 10}();

        // After play, pot must be 0 if a win occurred, otherwise it's any multiple of 10
        // The buggy version leaves pot == 1 after win; reference always 0 after win
        // We assert: pot is never 1; reference holds always, bug violates it
        assertTrue(c.pot() != 1);
    }
}

