pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint256 difficulty, uint256 warp) public {
        // bound parameters to keep them within reasonable ranges
        warp = bound(warp, 0, 1 days);
        difficulty = bound(difficulty, 0, type(uint256).max);
        seed = bound(seed, 0, 10 ether);

        // set up blockchain conditions to influence determinism
        vm.warp(warp);
        vm.roll(difficulty);

        // fund sender and execute play
        address sender = address(0x1);
        vm.deal(sender, 10 ether);
        vm.prank(sender);

        bool success;
        try c.play{value: 10}() {
            success = true;
        } catch {
            success = false;
        }

        // After any execution, pot is either 0 (reset after win) or NOT exactly 1 (loss, or reverted)
        // The buggy version can leave pot == 1 after a win, violating this invariant
        uint256 potAfter = c.pot();
        assertTrue(potAfter != 1);
    }
}

