// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 numPlays) public {
        // Bound the number of plays to keep execution reasonable
        numPlays = uint8(bound(numPlays, 1, 30));

        // We need a player with enough ether
        address player = makeAddr("player");
        vm.deal(player, numPlays * 10 ether);
        vm.prank(player);

        // Perform 'numPlays' consecutive play() calls
        for (uint8 i = 0; i < numPlays; i++) {
            c.play{value: 10}();
        }

        // The invariant: after any number of plays, if the last play resulted in a win,
        // pot should be 0 (because the contract resets it). The reference contract guarantees
        // that pot == 0 if the latest random was 0.
        // To express this universally, we assert that after the sequence, pot is either
        // the accumulated sum (if no win ever occurred) or 0 (if the last play was a win).
        // However, the fuzzer cannot directly observe random outcomes.
        // Instead, we rely on a derived invariant:
        // For the reference, the total balance of the contract (address(c).balance) should
        // always equal pot (since all value received is added to pot, and all payouts
        // drain pot). The bug breaks this because it fails to reset pot after a win
        // while still sending out the balance, leaving a non-zero pot that does not
        // match the contract's actual balance.
        // Actually, the contract's balance after transfers may be 0, but pot remains positive.
        // So we check: address(c).balance >= pot. For the reference, equality holds.
        // For the mutant, after a win, pot > address(c).balance, so the invariant fails.
        assertTrue(address(c).balance >= c.pot());
    }
}

