pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint8 warpBump) public {
        // Restrict warpBump so we don't overflow block.timestamp in Solidity 0.8
        vm.assume(warpBump <= 100);
        vm.warp(block.timestamp + warpBump);

        // First play: seed low bytes decide whether it's a win
        address player1 = makeAddr("player1");
        vm.deal(player1, 10 ether);
        vm.prank(player1);
        c.play{value: 10}();

        // Second play: a different player
        address player2 = makeAddr("player2");
        vm.deal(player2, 10 ether);
        vm.prank(player2);
        c.play{value: 10}();

        // After two plays, pot must be either 0, 10, or 20
        uint256 potVal = c.pot();
        assertTrue(potVal == 0 || potVal == 10 || potVal == 20);
    }
}

