pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint8 difficulty) public {
        vm.assume(timestamp > 0);
        vm.warp(timestamp);
        vm.roll(difficulty);
        // First play
        address player1 = address(0x1);
        vm.deal(player1, 10 ether);
        vm.prank(player1);
        try c.play{value: 10}() {} catch {}
        // Second play, only if first play was a win (pot = 0).
        // We want to check that after a win, pot is 0 before the next play.
        // We force a win by trying many times? No, the fuzzer supplies block conditions.
        // We just play twice; after the second play completes, check the invariant.
        address player2 = address(0x2);
        vm.deal(player2, 10 ether);
        vm.prank(player2);
        try c.play{value: 10}() {} catch {}
        // Invariant: pot must be either 0 (if second play was a win) or exactly 20 (if second play lost and first won or lost with pot rollover).
        // But the reference guarantees pot is 0 after any win, so after two plays, if the first was a win, pot is at most 20.
        // The buggy version fails to reset pot after a win, so after a win followed by a loss, pot could be 20 (first win didn't reset) plus 10 = 30.
        // The precise invariant: pot can only be 0, 10, or 20.
        // Because reference: after any win, pot resets to 0. So max pot after two plays is 20 (two losses).
        // Buggy: after win then loss, pot = 20 (not reset) + 10 = 30.
        assertTrue(c.pot() == 0 || c.pot() == 10 || c.pot() == 20);
    }
}

