contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 playCount) public {
        vm.assume(playCount > 0 && playCount <= 10);
        uint256 snapshot = vm.snapshot();
        for (uint8 i = 0; i < playCount; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i, block.timestamp)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
        }
        assertTrue(address(c).balance == c.pot() - (1 * playCount));
