pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 warpTs, uint256 diff) public {
        vm.assume(value > 0 && value <= 1 ether);
        vm.assume(diff <= type(uint256).max);
        vm.warp(warpTs);
        vm.roll(diff);
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        vm.prank(player);
        try c.play{value: value}() {
            uint256 potAfter = c.pot();
            assertTrue(potAfter == 0, "pot must be zero after successful play");
        } catch {
            // If the call reverts, the rule is trivially satisfied (no state change)
            assertTrue(true);
        }
    }
}

