pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value) public {
        // Admissible domain: value must be non-zero and at most the contract's pot can handle.
        // The reference requires msg.value == TICKET_AMOUNT (10). The mutant allows 11.
        // We limit value to a reasonable range to avoid overflow in pot, but keep it wide enough to include 10 and 11.
        vm.assume(value > 0 && value <= 100);

        // Arrange
        vm.deal(address(this), value);

        // Act: try to play with the fuzzed value
        bool success;
        try c.play{value: value}() {
            success = true;
        } catch {
            success = false;
        }

        // If the call succeeded, the resulting pot must be a multiple of the value sent.
        // This holds for the reference (value=10, pot becomes 0 after payout which is 0*10, or remains 10 after no payout which is 1*10).
        // The mutant fails when value=11 because the fee (1) and pot logic assume TICKET_AMOUNT=10, leaving a pot not divisible by 11.
        if (success) {
            uint256 finalPot = c.pot();
            assertTrue(finalPot % value == 0);
        }
    }
}

