// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 randomSeed) public {
        // randomSeed determines the random outcome: we pre-warp and pre-roll to control randomness
        vm.assume(randomSeed < 2);
        // We need the random inside play() to be 0 (win) to observe the pot inconsistency.
        // We can manipulate block.timestamp and block.difficulty to make keccak256(...)%2 == 0.
        // Use a brute-force approach: try different block.number and block.timestamp until we get a win.
        // But the fuzzer gives us randomSeed; we can just set block parameters so that the hash is even.
        // Since keccak256(abi.encodePacked(block.timestamp, block.difficulty)) % 2 == randomSeed,
        // we can iterate to find suitable values. However, Foundry has no loop in assumptions, so we
        // instead assume the random outcome is 0 (win) by directly forcing it via vm.warp and vm.roll.
        // To guarantee a win, we need keccak256(abi.encodePacked(timestamp, difficulty)) % 2 == 0.
        // We can set block.timestamp = 0 and block.difficulty = 0, then keccak256(...) is known.
        // Let's compute: uint(keccak256(abi.encodePacked(uint256(0), uint256(0)))) % 2. This is deterministic.
