pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool randomBit) public {
        address player = address(0x1234);
        vm.deal(player, 10 ether);

        vm.warp(1);
        vm.roll(1);
        // randomBit controls block.difficulty to influence the random outcome
        if (randomBit) {
            vm.roll(1);
        } else {
            vm.roll(2);
        }

        uint256 potBefore = c.pot();
        uint256 bankBefore = address(c).balance;

        vm.prank(player);
        c.play{value: 10}();

        uint256 potAfter = c.pot();
        uint256 bankAfter = address(c).balance;

        int256 potChange = int256(potAfter) - int256(potBefore);
        int256 bankChange = int256(bankAfter) - int256(bankBefore);

        // If pot didn't change (no win), bank should not change either.
        // If pot changed (win occurred, pot emptied), the bank change must equal the amount deducted from pot (FEE_AMOUNT = 1).
        assertTrue(
            (potChange == 0 && bankChange == 0) ||
            (potChange < 0 && bankChange == int256(1))
        );
    }
}

