    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Bound to avoid huge balances that could cause overflow in balance tracking.
        // The seed still controls the random path since play uses block data, not seed.
        vm.assume(seed < 1000);
        uint256 prePot = c.pot();
        uint256 preBank = c.bank().balance;
        uint256 preCBalance = address(c).balance;
        uint256 sentAmount = 10; // TICKET_AMOUNT is hardcoded in C

        address player = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.deal(player, sentAmount);
        vm.prank(player);

        bool ok = true;
        try c.play{value: sentAmount}() {
        } catch {
            ok = false;
        }
        if (!ok) {
            // If it reverted, the state should remain unchanged.
            assertEq(c.pot(), prePot);
            return;
        }

        uint256 postPot = c.pot();
        uint256 postBank = c.bank().balance;
        uint256 postCBalance = address(c).balance;

        uint256 deltaPot = postPot - prePot;
        uint256 deltaBank = postBank - preBank;
        uint256 deltaCBalance = postCBalance - preCBalance;

