                uint256 potBefore = c.pot();
                uint256 bankBalanceBefore = c.bank().balance;
                c.play{value: 10}();
                totalFeeSent += (bankBalanceBefore < c.bank().balance ? bankBalanceBefore - c.bank().balance : 0);
                // pot must be 0 after win
                assertEq(c.pot(), 0, "pot must be zero after win");
            } else {
                // loss scenario - pot increases
                c.play{value: 10}();
            }
        }

        // Invariant: bank's total received fees should only increase or stay same
        // Buggy version can decrease bank fees when pot is zero and winner gets pot instead of (pot-FEE)
        assertTrue(c.bank().balance >= initialBankBalance + totalFeeSent, "bank fees should be cumulative");
    }
}

